sp_widget.client_script:
function($scope, $rootScope, $timeout) {
  $scope.filtroAnoSelecionado = "";
  $scope.filtroBimestreSelecionado = "";

  $scope.filtroAnoChanged = function() {
    // Não limpa bimestre se ano for limpo
    $rootScope.$broadcast('filtroAnoSelecionado', $scope.filtroAnoSelecionado);
    console.log('Ano selecionado:', $scope.filtroAnoSelecionado);
  };

  $scope.filtroBimestreChanged = function() {
    // Não bloqueia nada, apenas transmite o valor
    $rootScope.$broadcast('filtroBimestreSelecionado', $scope.filtroBimestreSelecionado);
    console.log('Bimestre selecionado:', $scope.filtroBimestreSelecionado);
  };

  $timeout(function() {
    $scope.filtroBimestreSelecionado = "6";  // define 6º bimestre como padrão
    $scope.filtroAnoChanged();
    $scope.filtroBimestreChanged();
  });
}

sp_widget.css:
.breadcrumb-bar {
    font-family: "Roboto Flex", sans-serif;
    display: flex;
    align-items: center;
    justify-content: space-between;
    background-color: #f8faff;
    border-radius: .6rem;
    padding: .8rem 1.5rem;
    color: #1e3a8a;
    font-size: 24px;
    box-shadow: 0 .1rem .2rem rgba(0, 0, 0, .05);
    flex-wrap: wrap;
    gap: 10px;
    margin-top: 2rem; /* Mantido do seu original para espaçamento superior */
    margin-bottom: 1rem;
}

.breadcrumb-links {
    display: flex;
    align-items: center;
    gap: 6px;
}

.breadcrumb-links a {
    color: #2563eb;
    text-decoration: none;
    font-weight: 500;
}

.breadcrumb-links a:hover {
    text-decoration: underline;
}

.breadcrumb-links span {
    color: #64748b;
}

/* --- Container para agrupar os filtros --- */
.filters-wrapper {
    display: flex;
    align-items: center;
    gap: 20px;
    flex-wrap: wrap;
}

/* --- Estilo Individual do Filtro --- */
.breadcrumb-filter {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    gap: 2px;
}

.breadcrumb-filter label {
    font-size: 10px;
    font-weight: 600;
    color: #9fa4c3;
    display: flex;
    align-items: center;
    margin-left: 26px;
    margin-bottom: -2px;
    text-transform: uppercase;
}

/* Select com ícone interno e seta customizada */
.filter-select {
    position: relative;
    display: flex;
    align-items: center;
    z-index: 99;
}

/* Ícone de filtro à esquerda */
.filter-select i {
    color: white;
    -webkit-text-stroke: 1px #4b5563;
    font-size: 16px;
    pointer-events: none;
    padding-right: 10px;
}

/* Seta para baixo */
.filter-select::after {
    content: "v";
    position: absolute;
    right: 10px;
    top: 50%;
    transform: translateY(-50%) scaleY(0.9) scaleX(1.6);
    font-size: 14px;
    font-weight: 400;
    pointer-events: none;
    color: #334155;
}

/* Select estilizado */
.filter-select select {
    padding: 4px 26px 4px 8px;
    border: 1px solid #cbd5e1;
    border-radius: 6px;
    background-color: white;
    font-family: 'Roboto Flex', sans-serif;
    font-size: 13px;
    color: #334155;
    appearance: none;
    min-width: 130px; /* Um pouco maior para caber "Xº Bimestre" */
    cursor: pointer;
    height: 28px;
    display: flex;
    align-items: center;
}

.filter-select select:focus {
    outline: none;
    border-color: #2563eb;
    box-shadow: 0 0 0 2px rgba(37,99,235,0.2);
}

/* Responsividade */
@media (min-width: 375px) and (max-width: 819px) {
    .breadcrumb-bar {
        font-size: 1.5rem;
        flex-direction: column;
        align-items: flex-start;
        margin-top: 1rem;
    }
    .filters-wrapper {
        width: 100%;
        justify-content: space-between;
        margin-top: 10px;
    }
}

@media (min-width: 820px) {
    .breadcrumb-bar {
        font-size: 2.5rem;
    }
}

sp_widget.script:
(function() {
  var anos = [];
  var bimestres = ['1', '2', '3', '4', '5', '6'];

  var gr = new GlideRecord('x_sded9_portal_t_0_u_resultado_primario');
  gr.query();

  var anosUnicos = {};

  while (gr.next()) {
    var ano = gr.getValue('u_ano');
    if (ano && !anosUnicos[ano]) {
      anos.push(ano);
      anosUnicos[ano] = true;
    }
  }

  anos.sort(function(a, b) { return b - a; });

  data.anos = anos;
  data.bimestres = bimestres;
})();
